local rows={}
for _,group in ipairs(groups)do
  for _,cell in ipairs(group.cells)do
    local row={id=cell[1],quadrant=cell[2],sourceCells=cell[3],sourceFiles=files[group.files]}
    for key,value in pairs(group)do
      if key~='files' and key~='art' and key~='cells' then row[key]=value end
    end
    for key,value in pairs(art[group.art])do row[key]=value end
    rows[#rows+1]=row
  end
end
return rows
end)()
local function fenceKey(r)return table.concat({r.game,r.style,r.tileset,r.map or '',r.id,r.quadrant,r.x or '',r.y or ''},':')end
local fenceIndex={}for i,r in ipairs(rows)do fenceIndex[fenceKey(r)]=i end
local replaced,added=0,0
for _,r in ipairs(fenceUpdates)do local i=fenceIndex[fenceKey(r)];if i then rows[i]=r;replaced=replaced+1 else rows[#rows+1]=r;added=added+1 end end
assert(replaced==24 and added==0,'Native transparent fence source set changed')
-- END NATIVE TRANSPARENT FENCE BACKGROUNDS
return rows
